$ErrorActionPreference = 'Stop'

$desktopPath = [Environment]::GetFolderPath('Desktop')
$docPath = Join-Path $desktopPath 'VKR_Smyshlyaev.docx'
$backupPath = Join-Path $desktopPath 'VKR_Smyshlyaev_backup_before_ch2_edit.docx'

function Get-ParagraphText($paragraph) {
    return ($paragraph.Range.Text -replace '[\r\a]+$', '').Trim()
}

function Find-ParagraphIndex($document, $expectedText) {
    for ($i = 1; $i -le $document.Paragraphs.Count; $i++) {
        $text = Get-ParagraphText $document.Paragraphs.Item($i)
        if ($text -eq $expectedText) {
            return $i
        }
    }
    throw "Paragraph not found: $expectedText"
}

if (-not (Test-Path $docPath)) {
    throw "Document not found: $docPath"
}

Copy-Item -LiteralPath $docPath -Destination $backupPath -Force

$word = $null
$doc = $null
$createdWord = $false

try {
    try {
        $word = [Runtime.InteropServices.Marshal]::GetActiveObject('Word.Application')
    } catch {
        $word = New-Object -ComObject Word.Application
        $createdWord = $true
    }

    $word.Visible = $false

    foreach ($openDoc in $word.Documents) {
        if ($openDoc.FullName -eq $docPath) {
            $doc = $openDoc
            break
        }
    }

    if ($null -eq $doc) {
        foreach ($pv in $word.ProtectedViewWindows) {
            $candidate = Join-Path $pv.SourcePath ($pv.Caption -replace ' - защищенный просмотр$', '')
            if ($candidate -eq $docPath -or $pv.Caption -like 'VKR_Smyshlyaev*') {
                $doc = $pv.Edit()
                break
            }
        }
    }

    if ($null -eq $doc) {
        $doc = $word.Documents.Open($docPath)
    }

    $chapter2Index = Find-ParagraphIndex $doc 'Глава 2. Проектная часть'
    $chapter3Index = Find-ParagraphIndex $doc 'Глава 3. Практическая часть'
    $sectionHeadingIndex = Find-ParagraphIndex $doc '2.2. Проектирование приложения'

    $sectionStyle = $doc.Paragraphs.Item($sectionHeadingIndex).Range.Style
    $normalStyle = $doc.Paragraphs.Item($chapter2Index + 1).Range.Style

    $deleteStart = $doc.Paragraphs.Item($chapter2Index).Range.End
    $deleteEnd = $doc.Paragraphs.Item($chapter3Index).Range.Start
    $deleteRange = $doc.Range($deleteStart, $deleteEnd)
    $deleteRange.Text = ''

    $items = @(
        @{ Kind = 'text'; Text = 'Проектная часть основывается на результатах предпроектного анализа и переводит выявленные требования в набор конкретных проектных решений. В рамках данной главы определяются целевые бизнес-процессы системы, структура веб-приложения, логика пользовательского взаимодействия, состав данных и ограничения, влияющие на практическую реализацию решения.' },
        @{ Kind = 'heading'; Text = '2.1. Моделирование бизнес-процессов приложения' },
        @{ Kind = 'text'; Text = 'На этапе проектирования были выделены ключевые участники системы: пациент, врач и администратор. Для пациента основными процессами являются регистрация, авторизация, просмотр каталога врачей, выбор услуги, запись на прием, просмотр истории посещений, получение уведомлений и доступ к медицинским документам. Для врача критичными являются просмотр предстоящих приемов, изменение статусов визитов, загрузка медицинских документов и работа с результатами обследований. Для администратора важны управление карточками врачей, модерация отзывов, публикация акций и онлайн-консультаций, а также анализ сводных показателей работы клиники.' },
        @{ Kind = 'text'; Text = 'Центральным бизнес-процессом приложения выступает онлайн-запись на прием, поскольку именно этот сценарий связывает публичную часть сайта, личный кабинет пациента, расписание врача, механизм валидации временных слотов и сервис уведомлений. При моделировании данного процесса фиксируются следующие этапы: выбор врача, просмотр доступных дат и времени, проверка корректности данных пациента, резервирование слота, создание записи со статусом SCHEDULED и инициирование уведомления. Дополнительно проектируются смежные процессы: подтверждение или завершение приема врачом, загрузка файлов по конкретному визиту, подача заявки на верификацию врача и публикация контентных материалов в административном контуре.' },
        @{ Kind = 'text'; Text = '(В данный подраздел рекомендуется добавить диаграмму вариантов использования UML для ролей пациент, врач и администратор; BPMN-диаграмму процесса онлайн-записи на прием; диаграмму деятельности для процесса работы врача с приемом и медицинскими документами.)' },
        @{ Kind = 'heading'; Text = '2.2. Проектирование структуры веб-приложения медицинской информационной системы' },
        @{ Kind = 'text'; Text = 'С учетом требований, сформулированных в аналитической части, для системы выбрана клиент-серверная архитектура с разделением серверной логики на несколько сервисов. Клиентская часть реализует единый веб-интерфейс, через который пользователь получает доступ к публичным разделам сайта, личному кабинету пациента, кабинету врача и административной панели. Серверная часть распределена по функциональным контурам: модуль аутентификации и ролей, модуль работы с профилем пациента, модуль записи на прием и предметной логики клиники, а также модуль уведомлений.' },
        @{ Kind = 'text'; Text = 'Такое разбиение обусловлено различием ответственности и характером обрабатываемых данных. Контур аутентификации должен быть компактным и изолированным, пациентский контур — хранить персональные данные и обеспечивать доступ к ним, основной медицинский контур — включать расписание, карточки врачей, приемы, документы, отзывы и публичный контент, а модуль уведомлений — выполнять фоновые операции без блокировки пользовательских сценариев. Взаимодействие между частями системы строится по REST API для синхронных запросов и через брокер сообщений для асинхронной доставки событий.' },
        @{ Kind = 'text'; Text = 'Внутренняя структура веб-приложения также делится на логические интерфейсные блоки: публичную часть, кабинет пациента, кабинет врача и административный раздел. Такое проектирование облегчает навигацию, разграничение доступа и последующее сопровождение программного продукта. Отдельно предусматривается файловый контур для хранения изображений и медицинских вложений, а также реляционное хранение структурированных данных. Это позволяет отделить бизнес-сущности от бинарных объектов и сделать архитектуру более масштабируемой.' },
        @{ Kind = 'text'; Text = '(В данный подраздел рекомендуется добавить диаграмму компонентов UML с отображением frontend, auth-service, patient-service, appointment-service, notification-service, PostgreSQL, Kafka и MinIO; диаграмму развертывания UML с контейнерами и внешними зависимостями; контекстную схему взаимодействия компонентов системы.)' },
        @{ Kind = 'heading'; Text = '2.3. Разработка прототипов интерфейса приложения' },
        @{ Kind = 'text'; Text = 'Проектирование интерфейсов приложения выполнялось с ориентацией на различающиеся пользовательские роли и сценарии работы. Для публичной части приоритетом стали быстрый доступ к информации о врачах, услугах, акциях и онлайн-консультациях, а также наглядная форма записи на прием. Для кабинета пациента важны компактное представление истории записей, уведомлений, результатов анализов и медицинских документов. Интерфейс кабинета врача проектируется исходя из задач оперативной работы с приемами, статусами и прикрепляемыми файлами. Административная панель должна обеспечивать удобное редактирование контента и управление сущностями системы без перехода между избыточным числом экранов.' },
        @{ Kind = 'text'; Text = 'При разработке прототипов учитывается не только внешний вид страниц, но и логика переходов между ними. Для пациента важен сценарий от просмотра врача до подтверждения записи, для врача — быстрый переход от списка приемов к карточке конкретного визита, для администратора — последовательное управление карточками врачей, отзывами, новостями, акциями и аналитикой. Таким образом, прототип в проектной главе выступает не декоративным макетом, а моделью пользовательского взаимодействия, которая проверяет полноту функциональных требований и согласованность интерфейсной структуры с серверной логикой.' },
        @{ Kind = 'text'; Text = '(В данный подраздел рекомендуется добавить прототипы следующих экранов: главная страница и каталог врачей; форма онлайн-записи; личный кабинет пациента; кабинет врача; административная панель. Дополнительно целесообразно включить карту навигации по основным экранам приложения.)' },
        @{ Kind = 'heading'; Text = '2.4. Проектирование базы данных' },
        @{ Kind = 'text'; Text = 'Проектирование базы данных опирается на выделенные сущности предметной области и на выбранную сервисную архитектуру. В системе используются сущности учетной записи пользователя, профиля пациента, карточки врача, расписания, цен на услуги, записи на прием, отзыва, заявки на верификацию врача, медицинского документа, результата анализа, уведомления, акции, новости и онлайн-консультации. Каждая сущность фиксирует отдельный аспект предметной области, а связи между ними определяют правила хранения и обработки данных.' },
        @{ Kind = 'text'; Text = 'Для снижения связанности приложения данные распределяются между несколькими логическими хранилищами. В одном контуре хранятся учетные записи, роли и заявки на верификацию врача, в другом — персональные данные пациента, в третьем — основной набор медицинских и административных сущностей. Связи между контурами организуются через идентификаторы, а не через прямые внешние ключи между разными базами. Такой подход соответствует выбранной архитектуре и упрощает сопровождение системы. Для файловых объектов применяется отдельное объектное хранилище, тогда как в реляционной базе сохраняются ссылки на файлы и их метаданные.' },
        @{ Kind = 'text'; Text = 'Особое внимание при проектировании БД уделяется ограничениям целостности. Для записи на прием необходим контроль уникальности временного слота в рамках врача и даты, для медицинских документов — связь с конкретным визитом и пациентом, для уведомлений — привязка к пользователю и бизнес-событию. Кроме того, модель данных должна обеспечивать получение аналитических выборок по загрузке врачей, статусам приемов и пользовательской активности.' },
        @{ Kind = 'text'; Text = '(В данный подраздел рекомендуется добавить ER-диаграмму базы данных с основными сущностями и связями; логическую схему распределения таблиц по сервисам; при необходимости — диаграмму состояний для сущности Appointment со статусами SCHEDULED, CONFIRMED, COMPLETED, CANCELLED и NO_SHOW.)' },
        @{ Kind = 'heading'; Text = '2.5. Анализ реализуемости проекта' },
        @{ Kind = 'text'; Text = 'Технологическая реализуемость проекта оценивается как высокая, поскольку выбранный стек соответствует поставленным задачам и уже подтвержден структурой разработанного решения. Использование Java и Spring Boot позволяет формализовать предметную логику, обеспечить валидацию и разграничение доступа, PostgreSQL подходит для надежного хранения структурированных данных, Kafka — для асинхронных уведомлений, MinIO — для хранения файлов, а React — для построения единого пользовательского интерфейса. Развертывание через Docker Compose упрощает воспроизводимость среды и локальное тестирование системы.' },
        @{ Kind = 'text'; Text = 'Организационная реализуемость проекта также является достаточной, так как приложение ориентировано на типовые процессы частной клиники и не требует внедрения редких или узкоспециализированных технологий. Система может вводиться поэтапно: сначала как инструмент онлайн-записи и ведения кабинетов, затем как расширяемая платформа для документов, аналитики и контентного сопровождения. При этом необходимо учитывать ограничения проекта: отсутствие интеграции с внешними государственными медицинскими системами, повышенные требования к защите персональных данных и необходимость дальнейшего расширения автоматизированного тестирования.' },
        @{ Kind = 'text'; Text = 'С точки зрения дальнейшего развития проект сохраняет потенциал масштабирования. Архитектура допускает расширение набора ролей, подключение новых каналов уведомлений, развитие аналитического блока и интеграцию с дополнительными сервисами. Следовательно, принятые проектные решения являются не только достаточными для реализации выпускной квалификационной работы, но и пригодными для дальнейшей эволюции программного продукта в условиях реальной эксплуатации.' },
        @{ Kind = 'text'; Text = '(В данный подраздел рекомендуется добавить таблицу соответствия «требование — проектное решение — используемая технология», а также сводную схему, показывающую, какие функциональные и нефункциональные требования были закрыты на этапе проектирования.)' }
    )

    $insertPos = $doc.Paragraphs.Item($chapter2Index).Range.End
    foreach ($item in $items) {
        $range = $doc.Range($insertPos, $insertPos)
        $range.Text = $item.Text + "`r"
        if ($item.Kind -eq 'heading') {
            $range.Style = $sectionStyle
        } else {
            $range.Style = $normalStyle
        }
        $insertPos = $range.End
    }

    foreach ($toc in $doc.TablesOfContents) {
        $toc.Update()
    }
    $doc.Fields.Update() | Out-Null
    $doc.Save()

    Write-Output "Updated: $docPath"
    Write-Output "Backup: $backupPath"
}
finally {
    if ($null -ne $doc) {
        [void][Runtime.InteropServices.Marshal]::ReleaseComObject($doc)
    }
    if ($null -ne $word) {
        if ($createdWord) {
            $word.Quit()
        }
        [void][Runtime.InteropServices.Marshal]::ReleaseComObject($word)
    }
    [GC]::Collect()
    [GC]::WaitForPendingFinalizers()
}
